import { describe, expect, it } from 'vitest'
import { dataUriToBuffer } from './lighthouse.mjs'

describe('lighthouse worker helpers', () => {
  it('dataUriToBuffer converts base64 data URI to Buffer', () => {
    const dataUri = 'data:image/jpeg;base64,'
    const buffer = dataUriToBuffer(dataUri)
    expect(buffer).toBeInstanceOf(Uint8Array)
    expect(buffer.length).toBeGreaterThan(0)
  })

  it('dataUriToBuffer returns null for empty input', () => {
    expect(dataUriToBuffer('')).toBeNull()
    expect(dataUriToBuffer(null)).toBeNull()
  })
})
